export function tooltipFormatter(metric, fieldFormatter, fieldName, metricName) {
  if (!metric) {
    return '';
  }
  const details = [];
  if (fieldName && metric) {
    details.push({
      label: fieldName,
      value: metric.term
    });
  }
  if (metric) {
    details.push({
      label: metricName,
      value: fieldFormatter ? fieldFormatter.convert(metric.value, 'text') : metric.value
    });
  }
  return details;
}